// Teachers' planner — science & technology (מדע וטכנולוגיה, ממלכתי), grades 1–9. Shape: ./schema.js.
// Topics and hours per sub-topic: docs/curriculum/science.md (מפרטי התוכן תשפ״ז). The ministry sets no order within
// the year (the specification is arranged by content area), so units follow the specification's order; a few
// optional (רשות/הרחבה) topics that have no hours in the specification get hours of ours, as each grade's note says.
const s = (title, goal, activity, practice, links = []) => ({
  title, goal, activity, practice,
  links: links.map(slug => ({ type: 'lesson', slug: `science/${slug}` })),
})
const u = (id, title, hours, goals, concepts, steps) => ({ id, title, hours, goals, concepts, steps })

const BASE = 'https://meyda.education.gov.il/files/Pop/0files/mada-technology/'
const FILE = { 1: 'yesodi/content-specifications-1st.docx', 2: 'yesodi/content-specifications-2nd.docx', 3: 'yesodi/content-specifications-3rd.docx', 4: 'yesodi/content-specifications-4th.docx', 5: 'yesodi/content-specifications-5th.docx', 6: 'yesodi/content-specifications-6th.docx', 7: 'Chativat-Beynayim/mifrat-7th.docx', 8: 'Chativat-Beynayim/mifrat-8th.docx', 9: 'Chativat-Beynayim/mifrat-9th.docx' }
const LETTER = ['', 'א׳', 'ב׳', 'ג׳', 'ד׳', 'ה׳', 'ו׳', 'ז׳', 'ח׳', 'ט׳']
const seq = (grade, hoursPerWeek, yearly, extra, units) => ({
  subject: 'science', grade, hoursPerWeek, official: false,
  source: { title: `מפרט התכנים במדע וטכנולוגיה לכיתה ${LETTER[grade]} — תשפ״ז`, url: BASE + FILE[grade] },
  note: `הנושאים והשעות לקוחים ממפרט התכנים הרשמי (${yearly} שעות בשנה), אבל הסדר בתוך השנה הוא המלצה שלנו — המשרד אינו קובע סדר מחייב.${extra ? ' ' + extra : ''}`,
  units,
})

